function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return undefined;
  }

  console.log('thresholdStrings:', thresholdStrings);
  console.log('thresholdStrings type:', typeof thresholdStrings);
  console.log('Array.isArray:', Array.isArray(thresholdStrings));

  const thresholds = {};
  for (const str of thresholdStrings) {
    console.log('Processing:', str);
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${str}. Format must be <metric>=<number>`);
    }
    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);
    if (Number.isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold for ${metricId}: must be a number between 0 and 1, got ${valueStr}`);
    }
    thresholds[metricId] = value;
  }
  return thresholds;
}

try {
  const result = parseThresholds(['exact_match=0.4']);
  console.log('Result:', result);
} catch (e) {
  console.error('Error:', e.message);
}
EOF
node test_threshold.js
